mapper.select:
SELECT s.stu_id, u.real_name, u.phone
FROM my_student s, my_sys_user u
WHERE s.user_id = u.user_id AND s.student_no = #{stuNo}

SELECT s.stu_id, s.student_no, u.real_name, u.phone
FROM my_student s, my_sys_user u
WHERE s.user_id = u.user_id AND s.stu_id = #{stuId}

SELECT a.ca_id, a.stu_id, a.c_id, a.status, a.remark, a.appointment_time, a.create_time, c.c_name, c.type, c.current_person, c.max_person, c.start_time, c.end_time FROM my_course_appointment a, my_course c WHERE a.c_id = c.c_id AND a.stu_id = #{stuId} AND a.status IN (0, 1)
AND a.status = #{status}
ORDER BY a.create_time DESC

SELECT ca_id, stu_id, c_id, status, create_time
FROM my_course_appointment
WHERE ca_id = #{caId}
